function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const n = size === 'small' ? pick(1, 12) : pick(90, 100);
  const mode = Math.floor(rand() * 4);
  if (mode === 0) {
    // Mostly the four special letters, so many pairs can form.
    let s = '';
    for (let i = 0; i < n; i++) s += 'ABCD'[pick(0, 3)];
    return [s];
  }
  if (mode === 1) {
    // Any uppercase letters.
    let s = '';
    for (let i = 0; i < n; i++) s += letters[pick(0, 25)];
    return [s];
  }
  if (mode === 2) {
    // Nested removable blocks with a few blockers in between.
    let s = '';
    while (s.length < n) {
      const roll = rand();
      if (roll < 0.15) {
        s += 'ABCDXYZ'[pick(0, 6)];
        continue;
      }
      const depth = pick(1, 4);
      let open = '';
      let close = '';
      for (let d = 0; d < depth; d++) {
        if (rand() < 0.5) {
          open += 'A';
          close = 'B' + close;
        } else {
          open += 'C';
          close = 'D' + close;
        }
      }
      s += open + close;
    }
    return [s.slice(0, n)];
  }
  let s = '';
  for (let i = 0; i < n; i++) s += 'ABCDE'[pick(0, 4)];
  return [s];
}
